package com.trampolim.api.hub;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.ObjectProvider;import org.springframework.mock.web.*;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import java.util.*;
class HubLogoUploadFilterTest {
 @AfterEach void clear(){SecurityContextHolder.clearContext();}
 @SuppressWarnings("unchecked") @Test void anonymousCannotReachMultipartParser()throws Exception{var provider=(ObjectProvider<HubAccess>)mock(ObjectProvider.class);var response=new MockHttpServletResponse();new HubLogoUploadFilter(provider).doFilter(new MockHttpServletRequest("POST","/api/empresas/hub/organizations/42/logo"),response,(a,b)->fail("Anonymous multipart must not be parsed"));assertEquals(401,response.getStatus());verifyNoInteractions(provider);}
 @SuppressWarnings("unchecked") @Test void validatesAuthorityLengthAndTwoUploadSlotsBeforeParsing()throws Exception{var provider=(ObjectProvider<HubAccess>)mock(ObjectProvider.class);var access=mock(HubAccess.class);when(provider.getIfAvailable()).thenReturn(access);when(access.require("manager@fixture.test",42,true)).thenReturn(true);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken("manager@fixture.test",null,List.of()));var filter=new HubLogoUploadFilter(provider);var request=new MockHttpServletRequest("POST","/api/empresas/hub/organizations/42/logo");var response=new MockHttpServletResponse();filter.doFilter(request,response,(a,b)->fail("Unknown length"));assertEquals(411,response.getStatus());request.setContent(new byte[1114113]);response=new MockHttpServletResponse();filter.doFilter(request,response,(a,b)->fail("Oversize body"));assertEquals(413,response.getStatus());request.setContent(new byte[10]);filter.doFilter(request,new MockHttpServletResponse(),(a,b)->{var second=new MockHttpServletRequest("POST","/api/empresas/hub/organizations/42/logo");second.setContent(new byte[10]);filter.doFilter(second,new MockHttpServletResponse(),(c,d)->{var third=new MockHttpServletRequest("POST","/api/empresas/hub/organizations/42/logo");third.setContent(new byte[10]);var denied=new MockHttpServletResponse();filter.doFilter(third,denied,(e,f)->fail("Third concurrent upload"));assertEquals(429,denied.getStatus());});});var next=new MockHttpServletResponse();filter.doFilter(request,next,(a,b)->((jakarta.servlet.http.HttpServletResponse)b).setStatus(204));assertEquals(204,next.getStatus());verify(access,atLeastOnce()).require("manager@fixture.test",42,true);}
}
